#!/usr/bin/env python3
"""Fill a HWPX template by replacing {{...}} placeholders.

This script is tailored to Hancom HWPML (HWPX) XML where placeholder text may be
fragmented across multiple <hp:t> nodes inside a single paragraph (<hp:p>).

It:
- Loads /root/audit_overview.json and /root/corrective_actions.json
- Walks all XML-ish files under a working directory (e.g. /tmp/hwpx_work)
- For each <hp:p>, merges <hp:t> texts, performs placeholder replacements, then
  writes the replaced merged text back to the first <hp:t> and clears the rest
- Removes <hp:lineSegArray>/<hp:linesegarray> caches from modified paragraphs
- Rewrites dates from YYYY-MM-DD to YYYY.MM.DD across all text nodes
- Errors if any {{ or }} remain in any processed XML file

Usage:
  python3 /tmp/fill_hwpx.py /tmp/hwpx_work
"""

from __future__ import annotations

import json
import os
import re
import sys
import xml.etree.ElementTree as ET


DATE_RE = re.compile(r"\b(\d{4})-(\d{2})-(\d{2})\b")
PLACEHOLDER_RE = re.compile(r"\{\{([^{}]+)\}\}")


def localname(tag: str) -> str:
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def collect_and_register_namespaces(xml_path: str) -> dict[str, str]:
    """Return {prefix: uri} and register them to preserve prefixes on write."""
    ns_map: dict[str, str] = {}
    for event, item in ET.iterparse(xml_path, events=("start-ns",)):
        prefix, uri = item
        # ElementTree uses '' for default namespace
        if prefix in ns_map and ns_map[prefix] == uri:
            continue
        ns_map[prefix] = uri

    for prefix, uri in ns_map.items():
        ET.register_namespace(prefix if prefix is not None else "", uri)

    return ns_map


def iter_text_nodes_in_para(p: ET.Element) -> list[ET.Element]:
    # Text nodes are <hp:t> elements nested under <hp:run> (often), but to be safe
    # we collect any element with localname 't' under this paragraph.
    return [el for el in p.iter() if localname(el.tag) == "t"]


def remove_lineseg_caches(p: ET.Element) -> None:
    # HWPX sometimes uses either camelCase (lineSegArray/lineSeg) or lowercase
    # (linesegarray/lineseg). We remove both forms.
    targets = {"linesegarray", "lineseg", "lineSegArray", "lineSeg"}
    # Only remove direct children of <hp:p> to avoid accidentally removing
    # unrelated structures elsewhere.
    for child in list(p):
        if localname(child.tag) in targets:
            p.remove(child)


def severity_note_for_tier(tier: str) -> str:
    mapping = {
        "High": "즉시조치",
        "Medium": "계획보완",
        "Low": "모니터링",
    }
    return mapping.get(tier, "")


def build_replacements(overview: dict, actions: dict) -> tuple[dict[str, str], str, str]:
    summary = overview.get("summary", {})

    replacements: dict[str, str] = {}
    for k, v in summary.items():
        if isinstance(v, (str, int, float)):
            replacements[str(k)] = str(v)

    immediate = actions.get("immediate_actions", [])
    for idx in range(3):
        key = f"조치{idx+1}"
        replacements[key] = str(immediate[idx]) if idx < len(immediate) else ""

    raw_date = str(summary.get("점검일", ""))
    dotted_date = DATE_RE.sub(r"\1.\2.\3", raw_date) if raw_date else ""

    risk_tier = str(summary.get("위험등급", ""))

    return replacements, raw_date, dotted_date, risk_tier


def replace_in_paragraph(p: ET.Element, replacements: dict[str, str], risk_tier: str) -> bool:
    """Return True if paragraph text was modified."""
    t_nodes = iter_text_nodes_in_para(p)
    if not t_nodes:
        return False

    merged = "".join([(n.text or "") for n in t_nodes])
    if "{{" not in merged and "}}" not in merged:
        return False

    def repl(match: re.Match) -> str:
        key = match.group(1)
        if key == "위험등급":
            note = severity_note_for_tier(risk_tier)
            if note:
                return f"{risk_tier} {note}"
            return risk_tier
        return replacements.get(key, match.group(0))

    replaced = PLACEHOLDER_RE.sub(repl, merged)

    if replaced == merged:
        return False

    # Write the entire merged replaced string into the first node, clear rest.
    t_nodes[0].text = replaced
    for n in t_nodes[1:]:
        n.text = ""

    remove_lineseg_caches(p)
    return True


def rewrite_dates_everywhere(root: ET.Element) -> int:
    """Rewrite any YYYY-MM-DD literals to YYYY.MM.DD in all <...:t> nodes."""
    changed = 0
    for el in root.iter():
        if localname(el.tag) != "t":
            continue
        if not el.text:
            continue
        new = DATE_RE.sub(r"\1.\2.\3", el.text)
        if new != el.text:
            el.text = new
            changed += 1
    return changed


def file_contains_placeholders(path: str) -> bool:
    with open(path, "rb") as f:
        data = f.read()
    # Safe byte check; placeholders are ASCII.
    return b"{{" in data or b"}}" in data


def process_xml_file(path: str, replacements: dict[str, str], risk_tier: str) -> dict:
    collect_and_register_namespaces(path)
    tree = ET.parse(path)
    root = tree.getroot()

    modified_para_ids: list[str] = []

    for p in root.iter():
        if localname(p.tag) != "p":
            continue
        if replace_in_paragraph(p, replacements, risk_tier):
            modified_para_ids.append(p.get("id") or "")

    # Final pass: rewrite any dates anywhere.
    date_edits = rewrite_dates_everywhere(root)

    tree.write(path, encoding="UTF-8", xml_declaration=True)

    # Verify no placeholders remain.
    if file_contains_placeholders(path):
        # Provide a small hint by finding first occurrence in text form.
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            txt = f.read()
        idx = txt.find("{{")
        snippet = txt[max(0, idx - 80) : idx + 120] if idx != -1 else "(not found in text decode)"
        raise RuntimeError(f"Unreplaced placeholder remains in {path}. Snippet: {snippet}")

    return {
        "path": path,
        "modified_para_ids": [i for i in modified_para_ids if i],
        "date_edits": date_edits,
    }


def main() -> int:
    if len(sys.argv) != 2:
        print("Usage: python3 /tmp/fill_hwpx.py <working_dir>", file=sys.stderr)
        return 2

    workdir = sys.argv[1]

    with open("/root/audit_overview.json", "r", encoding="utf-8") as f:
        overview = json.load(f)
    with open("/root/corrective_actions.json", "r", encoding="utf-8") as f:
        actions = json.load(f)

    replacements, raw_date, dotted_date, risk_tier = build_replacements(overview, actions)

    # Ensure the replacement for 점검일 is dotted as well, to keep consistency even
    # if date placeholders are replaced before date rewrite pass.
    if raw_date and dotted_date:
        replacements["점검일"] = dotted_date

    # Process all XML-ish files under the working directory
    processed = []
    for root, _dirs, files in os.walk(workdir):
        for fn in files:
            if not (fn.lower().endswith(".xml") or fn.lower().endswith(".hpf")):
                continue
            processed.append(os.path.join(root, fn))

    processed.sort()

    results = []
    for p in processed:
        results.append(process_xml_file(p, replacements, risk_tier))

    # Print a compact summary for downstream validation.
    print(json.dumps({
        "processed_files": [r["path"] for r in results],
        "modified": {os.path.relpath(r["path"], workdir): r["modified_para_ids"] for r in results if r["modified_para_ids"]},
        "risk_tier": risk_tier,
    }, ensure_ascii=False, indent=2))

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

